goals.idle:
∀ {F V : Type u} [inst : AddCommGroup V] [inst_1 : Field F] [inst_2 : Module F V] {L : V →ₗ[F] V}
  {n : ℕ} (U : Fin n → Submodule F V),
  (¬∀ (i : Fin n), Submodule.map L (U i) = U i) → Submodule.map L (∑ i, U i) = ∑ i, U i

goals.implied:
